#!/usr/bin/env node
/**
 * Regenerate `bundles/router-presets/` from the preset sources in `preset/`.
 *
 * DSH 0.2.1 reads agent presets only from bundle patches, not from
 * `$DSH_HOME/.agent-presets/`. This script turns each `preset/<id>/` pair
 * (`preset.yml` + `agent.cordis.yml`) into one `@deepseek-ai/dsh-agent-preset`
 * declaration inside `bundles/router-presets/cordis.patch.yml`, and copies the
 * preset's `*.mjs` plugin assets next to it under
 * `bundles/router-presets/assets/<id>/`.
 *
 * Transforms applied to the legacy `agent.cordis.yml` entry list (verbatim
 * otherwise — comments, ordering and formatting are preserved by a pure
 * indentation shift):
 *
 *   1. persona `config.text:` -> `config.prefix:` (0.2.1 persona schema).
 *   2. plugin `name: ./<file>.mjs[?v=<n>]` -> `@dsh-external/dsh-router-presets/
 *      assets/<id>/<file>.mjs`: a relative name would resolve against the
 *      profile dir, not this bundle, and 404.
 *   3. a `workflow-ptc` row is inserted right before `- id: tool-workflow`,
 *      inside the delegation isolate group, because the web profile disables
 *      the host's own `workflow-ptc` row and the preset must supply its engine.
 *
 * Idempotent: running it twice produces byte-identical output.
 *
 * Usage: node scripts/build-preset-bundle.mjs
 */
import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = dirname(dirname(fileURLToPath(import.meta.url)))
const PRESET_DIR = join(ROOT, 'preset')
const BUNDLE_DIR = join(ROOT, 'bundles', 'router-presets')
const ASSETS_DIR = join(BUNDLE_DIR, 'assets')
const PATCH_FILE = join(BUNDLE_DIR, 'cordis.patch.yml')

const PACKAGE_NAME = '@dsh-external/dsh-router-presets'
/** Declaration order of the roster (order falls back to 1..n when preset.yml omits it). */
const PRESETS = ['router-standard', 'router-spec', 'router-react']
/** Indentation of the `plugins:` list inside a declaration row. */
const PLUGIN_INDENT = ' '.repeat(10)

const HEADER = [
  '# Generated by scripts/build-preset-bundle.mjs — do not edit by hand.',
  '#',
  '# Agent presets for DSH 0.2.1+: one `@deepseek-ai/dsh-agent-preset` row per',
  '# preset, carrying the entry list migrated from the legacy',
  '# `$DSH_HOME/.agent-presets/<id>/agent.cordis.yml` inline as `config.plugins`.',
  '#',
  '# Regenerate after editing preset/<id>/: node scripts/build-preset-bundle.mjs',
]

/** Read name/description/order from a legacy `preset.yml` (plain, line-oriented). */
function readPresetMeta(id) {
  const file = join(PRESET_DIR, id, 'preset.yml')
  const meta = {}
  for (const line of readFileSync(file, 'utf8').replace(/\r\n/g, '\n').split('\n')) {
    const match = line.match(/^(name|description|order):\s+(.*)$/)
    if (match === null) continue
    let value = match[2].trim()
    if (value.startsWith('"') && value.endsWith('"')) value = JSON.parse(value)
    else if (value.startsWith("'") && value.endsWith("'")) value = value.slice(1, -1).replaceAll("''", "'")
    meta[match[1]] = match[1] === 'order' ? Number(value) : value
  }
  if (typeof meta.name !== 'string' || meta.name === '') throw new Error(`${file}: no name`)
  if (typeof meta.description !== 'string' || meta.description === '') throw new Error(`${file}: no description`)
  return meta
}

/** Apply the three 0.2.1 transforms to one legacy entry list; return output lines. */
function transformPlugins(source, id, file) {
  const lines = source.replace(/\r\n/g, '\n').split('\n')
  while (lines.length > 0 && lines.at(-1).trim() === '') lines.pop()

  // 1. persona `text:` -> `prefix:` (config key rename only, value untouched).
  const persona = lines.findIndex((line) => /^\s*- id: persona\s*$/.test(line))
  if (persona === -1) throw new Error(`${file}: no \`- id: persona\` row`)
  const personaIndent = lines[persona].match(/^\s*/)[0].length
  let renamed = false
  for (let i = persona + 1; i < lines.length; i += 1) {
    const indent = lines[i].match(/^\s*/)[0].length
    if (indent <= personaIndent && /^\s*- /.test(lines[i])) break
    const key = lines[i].match(/^(\s*)text:(\s.*)$/)
    if (key !== null) {
      lines[i] = `${key[1]}prefix:${key[2]}`
      renamed = true
      break
    }
  }
  if (!renamed) throw new Error(`${file}: persona row has no \`text:\` key to rename`)

  // 2. relative plugin assets -> package subpaths of this bundle.
  const assetName = /^(\s*)name:\s+\.\/([A-Za-z0-9._-]+\.mjs)(?:\?v=\d+)?\s*$/
  for (let i = 0; i < lines.length; i += 1) {
    const match = lines[i].match(assetName)
    if (match !== null) lines[i] = `${match[1]}name: '${PACKAGE_NAME}/assets/${id}/${match[2]}'`
  }
  const leftover = lines.find((line) => /^\s*name:\s+\.\//.test(line))
  if (leftover !== undefined) throw new Error(`${file}: unmapped relative plugin name: ${leftover.trim()}`)

  // 3. presets own their workflow engine; insert it before the workflow tool row.
  const workflowTool = lines.findIndex((line) => /^\s*- id: tool-workflow\s*$/.test(line))
  if (workflowTool === -1) throw new Error(`${file}: no \`- id: tool-workflow\` row`)
  if (lines.some((line) => /^\s*- id: workflow-ptc\s*$/.test(line))) {
    throw new Error(`${file}: already carries a workflow-ptc row`)
  }
  const indent = lines[workflowTool].match(/^\s*/)[0]
  let insertAt = workflowTool
  while (insertAt > 0 && lines[insertAt - 1].trim() === '') {
    lines.splice(insertAt - 1, 1)
    insertAt -= 1
  }
  lines.splice(
    insertAt,
    0,
    `${indent}- id: workflow-ptc`,
    `${indent}  name: '@deepseek-ai/dsh-workflow-ptc'`,
    `${indent}  config:`,
    `${indent}    provider: spawn`,
    '',
  )

  return lines.map((line) => (line.trim() === '' ? '' : PLUGIN_INDENT + line))
}

/** Compose the whole patch file from the preset sources. */
function buildPatch() {
  const out = [...HEADER, '- insert:']
  PRESETS.forEach((id, index) => {
    if (index > 0) out.push('')
    const meta = readPresetMeta(id)
    const pluginsFile = join(PRESET_DIR, id, 'agent.cordis.yml')
    const body = transformPlugins(readFileSync(pluginsFile, 'utf8'), id, pluginsFile)
    out.push(
      `    - id: preset-${id}`,
      `      name: '@deepseek-ai/dsh-agent-preset'`,
      '      config:',
      `        id: ${id}`,
      `        name: ${JSON.stringify(meta.name)}`,
      `        description: ${JSON.stringify(meta.description)}`,
      `        order: ${meta.order ?? index + 1}`,
      '        plugins:',
      ...body,
    )
  })
  return `${out.join('\n').replace(/\n+$/, '')}\n`
}

/** Copy every `.mjs` asset of one preset into the bundle, pruning stale copies. */
function syncAssets(id) {
  const from = join(PRESET_DIR, id)
  const to = join(ASSETS_DIR, id)
  mkdirSync(to, { recursive: true })
  const wanted = readdirSync(from).filter((name) => name.endsWith('.mjs')).sort()
  for (const name of readdirSync(to)) {
    if (!wanted.includes(name)) rmSync(join(to, name), { recursive: true, force: true })
  }
  for (const name of wanted) copyFileSync(join(from, name), join(to, name))
  return wanted.length
}

/** Write only when bytes changed, so a no-op run leaves the tree untouched. */
function writeIfChanged(file, text) {
  const previous = existsSync(file) ? readFileSync(file, 'utf8') : undefined
  if (previous === text) {
    console.log(`unchanged ${file.slice(ROOT.length + 1)}`)
    return
  }
  writeFileSync(file, text)
  console.log(`wrote     ${file.slice(ROOT.length + 1)}`)
}

mkdirSync(ASSETS_DIR, { recursive: true })
writeIfChanged(PATCH_FILE, buildPatch())
for (const id of PRESETS) console.log(`assets    bundles/router-presets/assets/${id}/ (${syncAssets(id)} files)`)